CREATE   VIEW [CE].[vwCaseconduct]
AS
SELECT
	cc.[apuk_caseconductid],
	cc.[apuk_name],
	cc.[createdon],
	cc.[createdby],
	cc.[CreatedByName],
	cc.[modifiedon],
	cc.[modifiedby],
	cc.[ModifiedByName],
	cc.[ownerid],
	cc.[OwnerIdName],
	cc.[owningbusinessunit],
	cc.[owningbusinesunitName],
	cc.[apuk_type],
	cc.[apuk_type_description],
	cc.[apuk_solicitordecisionrecordedby],
	cc.[apuk_solicitordatedecisionmade],
	cc.[apuk_showonline],
	cc.[apuk_ruleofconduct2],
	cc.[apuk_ruleofconduct2Name],
	cc.[apuk_subject],
	cc.[apuk_subjectName],
	cc.[apuk_responsibleprincipal],
	cc.[apuk_resourcegroupid],
	cc.[apuk_regulatedschemeid],
	cc.[apuk_memberid],
	cc.[apuk_regulatedfirmid],
	cc.[apuk_regardingtype],
	cc.[apuk_regardingtype_Description],
	cc.[overriddencreatedon],
	cc.[apuk_rationale],
	cc.[processid],
	cc.[apuk_overturnrulebreach],
	cc.[apuk_primarylocationid],
	cc.[apuk_lettersenton],
	cc.[apuk_lettersentbyid],
	cc.[apuk_hradecisionmakerid],
	usrHraDescMakerId.[FullName] AS [apuk_hradecisionmakeridName],
	cc.[apuk_hradecision],
	hradecission.[LocalizedLabel] AS [apuk_hradecision_description],
	cc.[apuk_headofregulationsreviewoutcomenotes],
	cc.[apuk_headofregulationsreviewoutcome],
	cc.[apuk_headofregulationsreviewoutcome_Description],
	cc.[apuk_followupcompleted],
	cc.[apuk_evidencebundlereviewed],
	cc.[apuk_escalationlevel],
	cc.[apuk_escalationlevel_Description],
	cc.[apuk_decisiondate],
	cc.[apuk_regulatorycontactid],
	cc.[apuk_conductpaneloutcome],
	cc.[apuk_conductpaneloutcome_Description],
	cc.[apuk_comments],
	cc.[apuk_closurelettersent],
	cc.[apuk_casestatus],
	cc.[apuk_casestatus_Description],
	cc.[apuk_casereference],
	cc.[apuk_casepriority],
	cc.[apuk_casepriority_Description],
	cc.[apuk_casegroupreference],
	cc.[apuk_casedescription],
	cc.[apuk_caseclosuredate],
	cc.[apuk_caseclosed],
	cc.[apuk_bundlesavedtocase],
	cc.[apuk_bundlepreparationcomplete],
	cc.[apuk_bundlecompletedon],
	cc.[apuk_bundlecompletedbyid],
	usrBundleComplBy.[FullName] AS [apuk_bundlecompletedbyidName],
	cc.[apuk_areaofpractice],
	cc.[apuk_areaofpracticeName],
	cc.[apuk_areaofbreach3],
	cc.[apuk_areaofbreach3Name],
	cc.[apuk_areaofbreach2],
	cc.[apuk_areaofbreach2Name],
	cc.[apuk_areaofbreach],
	cc.[apuk_areaofbreachName],
	cc.[apuk_ageofcase],
	cc.[statecode],
	cc.[StateCode_Description],
	cc.[statuscode],
	cc.[StatusCode_Description]
FROM [synapse_ce].[vwCaseconduct] cc
	LEFT JOIN CE.vwSystemUser usrBundleComplBy
		ON cc.[apuk_bundlecompletedbyid] = usrBundleComplBy.[SystemUserId]
	LEFT JOIN CE.vwSystemUser usrHraDescMakerId
		ON cc.[apuk_hradecisionmakerid] = usrHraDescMakerId.[SystemUserId]
	LEFT JOIN synapse_ce.GlobalOptionSetMetadata hradecission
		ON cc.[apuk_hradecision] = hradecission.[Option]
			AND hradecission.[OptionSetName] = 'apuk_hradecision'
			AND hradecission.[entityname] = 'apuk_caseconduct'
